contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dep, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep);
        require(dep > 0);
        require(amount == dep);

        c.deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint256 balBefore = address(this).balance;
        uint256 cBefore = address(c).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted && address(this).balance == balBefore + amount && address(c).balance == cBefore - amount);
    }

    receive() external payable {}
}

