// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dep, uint256 amount) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        vm.assume(dep > 0);
        amount = dep;
        try c.deposit{value: dep}() {} catch { return; }
        uint256 balBefore = address(this).balance;
        uint256 cBefore = address(c).balance;
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(this).balance == balBefore + amount && address(c).balance == cBefore - amount);
    }

    function testFuzz_run(uint256 dep, uint256 amount) public {
        _run(dep, amount);
    }

    receive() external payable {}
}
